content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #cbd5e1;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.app-container {
  width: 100%;
  max-width: 600px;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2rem;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 1.5rem;
  color: var(--text-main);
}

.converter-card {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rremi;
  gap: 0.5rem;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input-field,
.select-field {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background-color: #fff;
  color: var(--text-main);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-field:focus,
.select-field:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.result-section {
  margin-top: 1rem;
  border-top: 1px solid #e2e8f0;
  padding-top: 1.5rem;
}

.result-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--text-main);
}

.grid-results {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
}

.result-item {
  background-color: #f1f5f9;
  padding: 0.875rem 1rem;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.result-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.result-value {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--primary-color);
  word-break: break-all;
}

.quick-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.preset-btn {
  background-color: #e2e8f0;
  border: none;
  border-radius: 6px;
  padding: 0.375rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-main);
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
}

.preset-btn:hover {
  background-color: var(--primary-color);
  color: #fff;
}

import { useState } from 'react';

type UnitKey = 'mm' | 'cm' | 'm' | 'km' | 'in' | 'ft';

interface UnitInfo {
  name: string;
  toMeters: number;
}

const units: Record<UnitKey, UnitInfo> = {
  mm: { name: 'ミリメートル (mm)', toMeters: 0.001 },
  cm: { name: 'センチメートル (cm)', toMeters: 0.01 },
  m: { name: 'メートル (m)', toMeters: 1 },
  km: { name: 'キロメートル (km)', toMeters: 1000 },
  in: { name: 'インチ (in)', toMeters: 0.0254 },
  ft: { name: 'フィート (ft)', toMeters: 0.3048 },
};

export default function App() {
  const [value, setValue] = useState<string>('1');
  const [unit, setUnit] = useState<UnitKey>('m');

  const numValue = parseFloat(value);
  const meters = isNaN(numValue) ? 0 : numValue * units[unit].toMeters;

  const handlePreset = (val: string, u: UnitKey) => {
    setValue(val);
    setUnit(u);
  };

  return (
    <div className="app-container">
      <h1 className="title">長さ単位変換ツール</h1>
      <div className="converter-card">
        <div className="input-group">
          <label className="label">変換する値</label>
          <input
            type="number"
            className="input-field"
            value={value}
            onChange={(e) => setValue(e.target.value)}
            placeholder="数値を入力..."
          />
          <div className="quick-presets">
            <button type="button" className="preset-btn" onClick={() => handlePreset('100', 'mm')}>100 mm</button>
            <button type="button" className="preset-btn" onClick={() => handlePreset('10', 'cm')}>10 cm</button>
            <button type="button" className="preset-btn" onClick={() => handlePreset('1', 'm')}>1 m</button>
            <button type="button" className="preset-btn" onClick={() => handlePreset('1', 'km')}>1 km</button>
            <button type="button" className="preset-btn" onClick={() => handlePreset('12', 'in')}>12 in</button>
            <button type="button" className="preset-btn" onClick={() => handlePreset('3', 'ft')}>3 ft</button>
          </div>
        </div>

        <div className="input-group">
          <label className="label">基準の単位</label>
          <select
            className="select-field"
            value={unit}
            onChange={(e) => setUnit(e.target.value as UnitKey)}
          >
            {(Object.keys(units) as UnitKey[]).map((key) => (
              <option key={key} value={key}>
                {units[key].name}
              </option>
            ))}
          </select>
        </div>

        <div className="result-section">
          <h2 className="result-title">変換結果</h2>
          <div className="grid-results">
            {(Object.keys(units) as UnitKey[]).map((key) => {
              const converted = meters / units[key].toMeters;
              const formatted = isNaN(converted)
                ? '0'
                : Number(converted.toFixed(6)).toString();

              return (
                <div className="result-item" key={key}>
                  <span className="result-label">{units[key].name}</span>
                  <span className="result-value">{formatted}</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
